check(close(ClassifierChain(GaussianNB(), order=[1, 0, 2]).fit(X, Yc).predict(Q), cc_pred), "cc pred")
Yb = np.column_stack(((y > 0).astype(int), (X[:, 0] > 0).astype(int)))
